css:
.loader {
  position: relative;
  width: 56px;
  height: 36px;
  border: 3px solid #6366f1;
  border-radius: 6px;
  box-sizing: border-box;
}
.loader::before {
  content: "";
  position: absolute;
  top: 9px;
  left: 15px;
  right: 15px;
  height: 4px;
  border-radius: 2px;
  background: #c7d2fe;
}
.loader i {
  position: absolute;
  top: 50%;
  width: 14px;
  height: 14px;
  margin-top: -7px;
  border-radius: 50%;
  border: 2px solid #6366f1;
  box-sizing: border-box;
  background:
    linear-gradient(#6366f1, #6366f1) center / 2px 100% no-repeat,
    linear-gradient(#6366f1, #6366f1) center / 100% 2px no-repeat;
  animation: spin 1s linear infinite;
}
.loader i:nth-child(1) { left: 7px; }
.loader i:nth-child(2) { right: 7px; }
@keyframes spin { to { transform: rotate(360deg); } }
